export const MONSTER = Object.fromEntries(MONSTERS.map((m) => [m.id, m]));

/** 通常の敵（ボス・ゴブリン・柱以外） */
export const NORMAL_MONSTERS = MONSTERS.filter((m) => !m.boss && !m.kind);
export const GOBLINS = MONSTERS.filter((m) => m.kind === 'goblin');
export const RIFT_GUARDIANS = MONSTERS.filter((m) => m.kind === 'guardian');
export const GATEKEEPERS = MONSTERS.filter((m) => m.kind === 'gatekeeper');
